#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-26
# Validation run of one Isaac family on its -fishfastid image (fastdds1 identity layer): sweep (lttng x1, tier default + the
# TASK 4 extra events), link the session into ~/fish_traces, post_run_pipeline (ingest -> model -> ... -> extractor), then the
# evidence histogram of the task edges. Usage: scripts/fastdds1_validate.sh <family> [dest_base]
set -u; cd "$(dirname "$0")/.."
F=${1:?family}; LD=${2:-$HOME/fish_traces/fastdds1_20261026}; mkdir -p "$LD"
log() { echo "[$(date +%T)] $*" | tee -a "$LD/validate.log"; }
EV=ros2:fish_msg_retain,ros2:fish_msg_release,ros2:fish_msg_type,ros2:fish_msg_stamp,ros2:fish_msg_ids
IMG=fish-r2b-$F-fishfastid:latest; docker image inspect $IMG >/dev/null 2>&1 || { log "$F: image $IMG missing"; exit 2; }
log "$F: run on $IMG"
IMG_OVERRIDE=$IMG REPS=1 MODES=lttng DEST_BASE="$LD/runs" SMOKE_TIMEOUT=1200 FISH_EXTRA_EVENTS=$EV \
  bash scripts/overhead_sweep_v8.sh "$F" > "$LD/sweep_$F.log" 2>&1 || log "$F: sweep rc=$?"
log "  $F: $(grep "^$F,lttng" "$LD/runs/runs.csv" 2>/dev/null | tail -1)"
D=$(ls -d "$LD"/runs/$F/lttng_1/fish_2* 2>/dev/null | tail -1); [ -n "$D" ] || { log "$F: no session dir"; exit 3; }
S=$(basename "$D"); [ -e "$HOME/fish_traces/$S" ] || ln -s "$D" "$HOME/fish_traces/$S"; echo "$S $F" >> "$LD/sessions_map.txt"
log "$F: session $S -> pipeline"
A=$HOME/fish_traces/analysis_$S
bash scripts/post_run_pipeline.sh "$S" "$A" > "$LD/pipeline_$F.log" 2>&1 || log "$F: pipeline rc=$?"
grep -E "FAILED|PIPELINE DONE" "$LD/pipeline_$F.log" | head -5 | sed 's/^/  /' | tee -a "$LD/validate.log"
log "$F: new events: $(PGPASSWORD=fish psql -h localhost -U fish -d fish -At -c "SELECT event||'='||count(*) FROM ros2_trace WHERE session_id='$S' AND event IN ('ros2:fish_rmw_write','ros2:fish_rmw_take_id','ros2:fish_rclcpp_intra_take','ros2:fish_rclcpp_intra_publish') GROUP BY event ORDER BY event" | tr '\n' ' ')"
grep -E "Fast DDS identity|intra-process identity|dds pairs by|trigger edges with instances" "$A/fish_tasks.txt" 2>/dev/null | cut -c1-300 | sed 's/^/  /' | tee -a "$LD/validate.log"
python3 - "$A/fish_tasks.json" <<'PY' | tee -a "$LD/validate.log"
import json, sys, collections
d = json.load(open(sys.argv[1])); c = collections.Counter(); ci = collections.Counter()
for t in d.get('tasks', []):
    for e in t.get('edges', []): c[f"{e.get('kind')}:{e.get('prov')}"] += 1
for e in d.get('inactive_edges', []): ci[f"{e.get('kind')}:{e.get('prov')}"] += 1
print("  task edge evidence:", dict(c)); print("  inactive edge evidence:", dict(ci)); print("  candidates:", len(d.get('candidates', [])), "unpaired:", len(d.get('unpaired', [])))
PY
log "$F: VALIDATION DONE"
